"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[38164],{38164:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/almond.png\\"\\n          title=\\"Almond\\"\\n          author=\\"Sohn Won-pyung\\"\\n          publisher=\\"Changbi\\"\\n          publishedDate=\\"2017-03-31\\"\\n          isbn=\\"9788936456788\\"\\n          rating=4.5\\n          tags=\\"novel\\"\\n        />\\n</center>\\n\\n## Review\\nIt seems to pose a fundamental question about what ```empathy``` is to us living in an age of <mark>inability to empathize</mark>.  \\nIt sharply points out the appearance of modern society that has become insensitive to the sadness of others.  \\n<br>\\nLooking at the final scene of this book, it concludes with sudden, nonsensical miracles.  \\nSo I think this book ultimately ended as a sad ending, leaving behind a fantasy containing the protagonist\'s hope.  "}')}}]);